contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // The single public test function. Parameters control deposit amount and a sendMoney call.
    function run(address target, uint256 depositAmount, uint256 sendAmount, bytes calldata data) public payable {
        require(address(this).balance >= depositAmount, "need balance to deposit");
        // Record before values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBalance = address(c).balance;

        // Make C receive Ether by sending depositAmount from this contract to c
        // Ensure this contract has enough balance (checked above)
        // This is a top-level state-changing call
        (bool okDeposit,) = address(c).call{value: depositAmount}("");
        // record whether deposit succeeded (it should if depositAmount >= 0 and no reentrancy etc.)
        bool depositReverted = !okDeposit;

        // Now attempt withdrawAll (onlyOwner). Since this InvMutTest deployed C, it is the owner and msg.sender here
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Attempt withdraw of sendAmount
        bool withdrawReverted;
        try c.withdraw(sendAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt sendMoney to target with sendAmount and data
        bool sendMoneyReverted;
        try c.sendMoney(target, sendAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after-values
        uint256 afterCount = c.depositsCount();
        uint256 afterBalance = address(c).balance;

        // General rule (single assert):
        // 1) If the deposit call did not revert, depositsCount increased by exactly 1 and contract balance increased by depositAmount.
        // 2) Since this contract is owner, withdrawAll, withdraw and sendMoney must not revert. If they do revert, that's a violation.
        // 3) None of the withdraw/send calls should change depositsCount (depositsCount only changes via receive()).
        assert(
            (
                // deposit succeeded case
                (depositReverted == false && afterCount == beforeCount + 1 && afterBalance == beforeBalance + depositAmount)
                ||
                // deposit reverted case: no change
                (depositReverted == true && afterCount == beforeCount && afterBalance == beforeBalance)
            )
            &&
            // owner-only actions called by this contract must not revert
            withdrawAllReverted == false && withdrawReverted == false && sendMoneyReverted == false
            &&
            // depositsCount unchanged by withdraw/sendMoney
            afterCount >= beforeCount // already ensured above; keep non-underflow check
        );
    }

    // Accept Ether so C can call back into this contract during sendMoney/withdraw
    receive() external payable { }
}

contract InvMutTest {
