    function run(address target, uint256 depositAmount, uint256 sendAmount, bytes calldata data) public payable {
        require(address(this).balance >= depositAmount, "need balance for deposit");

        // Read before values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBalance = address(c).balance;

        // Make C receive Ether by sending depositAmount from this contract to c
        // Top-level state-changing call (low-level call to trigger receive)
        (bool okDeposit, ) = address(c).call{value: depositAmount}("\x00");

        // Try owner-only operations as top-level calls and capture whether they reverted
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool withdrewReverted;
        try c.withdraw(sendAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, sendAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after values
        uint256 afterCount = c.depositsCount();
        uint256 afterBalance = address(c).balance;

        // General rule (single assert):
        // - If the low-level deposit call succeeded (okDeposit==true), then depositsCount increased by exactly 1 and balance increased by exactly depositAmount.
        // - If the low-level deposit call failed, neither depositsCount nor balance changed.
        // - Regardless of deposit success, owner-only actions invoked by this contract must not change depositsCount (i.e., afterCount == beforeCount + (okDeposit?1:0)).
        // - Also assert that owner-only calls do not revert (they should succeed because this contract deployed C and is owner).
        assert(
            (okDeposit == true && afterCount == beforeCount + 1 && afterBalance == beforeBalance + depositAmount || okDeposit == false && afterCount == beforeCount && afterBalance == beforeBalance)
            && withdrewAllReverted == false
            && withdrewReverted == false
            && sendMoneyReverted == false
        );
    }

    receive() external payable { }
}

