contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters: target address to call from C, value to forward, and calldata.
    function run(address target, uint value, bytes calldata data) public payable {
        // Ensure this contract has enough balance if it will forward Ether through calls
        if (value > 0) require(address(this).balance >= value);

        // Observe before-values
        address beforeOwner = c.owner();
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Make the call that may change C's state. sendMoney is onlyOwner, and this contract is the owner.
        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        address afterOwner = c.owner();
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted for all inputs: the owner must remain unchanged (this contract)
        // and depositsCount must never decrease. Also, the contract's balance can only decrease by at most value
        // (since sendMoney may forward up to value), and cannot increase as a result of sendMoney.
        assert(
            afterOwner == beforeOwner
            && afterDeposits >= beforeDeposits
            && (beforeBalance >= afterBalance)
            && (beforeBalance - afterBalance <= value)
        );
    }

    // Allow receiving Ether so sendMoney and deposits can be tested.
    receive() external payable {}
}

