    constructor(C _c) { c = _c; }

    // Parameters: target to call, amount to forward from C, and calldata
    function run(address target, uint value, bytes calldata data) public payable {
        // If this test will forward Ether from itself (not from C), ensure it has enough balance
        if (value > 0) require(address(this).balance >= value);

        // Observe before-values
        address beforeOwner = c.owner();
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Make the call that may change C's state. sendMoney is onlyOwner; this contract is owner.
        bool reverted;
        try c.sendMoney(target, value, data) {
