        }

        // Observe after-values
        address afterOwner = c.owner();
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Assert the general invariant: owner unchanged, depositsCount never decreases,
        // C's balance does not increase, and decreases by at most `value`.
        assert(
            afterOwner == beforeOwner
            && afterDeposits >= beforeDeposits
