}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tests: try withdraw and withdrawAll from this contract (which is the owner),
    // and from a non-owner by simulating via external call using call on address(c).
    // However, we cannot change msg.sender when calling c from here: the InvMutTest is the deployer/owner.
    // To test non-owner behavior we rely on calling C.withdraw via address.call with encoded selector
    // so that msg.sender is still this contract — but we cannot simulate another sender inside this single transaction.
    // Instead, we test the invariant that withdraw and withdrawAll when called by the owner do not increase c's balance,
    // and that a plain low-level call from this contract that encodes withdraw with extra value will not increase c's balance
    // beyond the sent value. Additionally we assert that when owner calls withdraw(x) the contract balance decreases by at most x
    // and withdrawAll drains at most the full balance.

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // Record initial balances
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Make the contract receive Ether by sending to its receive() via address.call with value
        // depositAmount could be zero
        if (depositAmount > 0) {
            (bool ok,) = address(c).call{value: depositAmount}("\x00");
            // call to receive() should succeed because receive increments depositsCount and has no owner check
            // but if it reverted, we don't require it here — we simply record balances
            // ensure call did not revert by requiring ok or allowing failed deposit (balance stays same)
        }

        uint midC = address(c).balance;

        // As owner (this contract is owner since c was deployed by this contract), attempt withdraw(withdrawAmount)
        bool withdrawReverted;
        uint afterWithdrawC;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
            afterWithdrawC = address(c).balance;
        } catch {
            withdrawReverted = true;
            afterWithdrawC = address(c).balance;
        }

        // Now attempt withdrawAll(); capture revert flag and balance after
        bool withdrawAllReverted;
        uint afterWithdrawAllC;
        try c.withdrawAll() {
            withdrawAllReverted = false;
            afterWithdrawAllC = address(c).balance;
        } catch {
            withdrawAllReverted = true;
            afterWithdrawAllC = address(c).balance;
        }

        // General rule to assert:
        // 1) Neither withdraw nor withdrawAll can increase the contract balance.
        // 2) If withdraw did not revert, the decrease in c balance is <= withdrawAmount.
        // 3) If withdrawAll did not revert, the balance after withdrawAll is <= balance before withdrawAll.
        // Compose into single assertion using only observed values and params.

        assert(
            // (1): afterWithdrawC <= midC and afterWithdrawAllC <= afterWithdrawC
            (afterWithdrawC <= midC)
            && (afterWithdrawAllC <= afterWithdrawC)
            // (2): if withdraw succeeded then midC - afterWithdrawC <= withdrawAmount
            && (withdrawReverted || (midC - afterWithdrawC <= withdrawAmount))
        );
    }

    receive() external payable { }
}

