        deployer = msg.sender; // address that deployed InvMutTest (not used further)
    }

    // single public test function: params choose caller role and amount for deposits and withdrawal
    function run(address caller, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");
        require(caller != address(0), "caller cannot be zero");

        // 1) Make a deposit to C by sending Ether from this contract
        // To do that, call C.receive via a plain payable call to c
        // ensure we have balance then send depositAmount
        if (depositAmount > 0) {
            // send depositAmount to C; this increments depositsCount in C
            (bool okDeposit, ) = address(c).call{value: depositAmount}("");
            require(okDeposit, "deposit failed");
        }

        // record observable before-values
        uint beforeBalance = address(c).balance;
        uint beforeDepositsCount = c.depositsCount();
        address owner = c.owner();

        // 2) Attempt withdraw by impersonating either owner or non-owner
        // We cannot change msg.sender when calling c from here; instead we simulate two cases:
        // - If caller == owner, call should succeed and transfer funds out to this contract (since owner is msg.sender of that call).
        // - If caller != owner, calling withdraw should revert.
        // We implement by branching on whether the provided 'caller' equals observed owner and then performing the corresponding call

        bool reverted;
        if (caller == owner) {
            // Call withdrawAll as owner: but msg.sender for calls to c will be this InvMutTest contract, not 'caller'.
            // To make the call behave as owner, require that this contract is the owner. Check that and only then call.
            // If this contract is not the owner, then attempting to model owner behavior is impossible; in that case we instead assert the general rule must still hold: non-owner withdraws revert.
            if (address(this) == owner) {
                // perform withdrawAll which should succeed and empty the contract balance
                try c.withdrawAll() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // cannot act as owner; call withdrawAll and record whether it reverted (it should revert because this contract is not owner)
                try c.withdrawAll() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // Caller is not the owner; any withdraw by this contract should revert because this contract is not the owner unless this contract equals owner.
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        uint afterBalance = address(c).balance;
        uint afterDepositsCount = c.depositsCount();

        // GENERAL ASSERTION:
        // - depositsCount must have increased by exactly 1 iff depositAmount > 0 (because receive increments once per successful deposit call)
        // - If this contract was owner and we called withdrawAll (i.e., caller==owner and address(this)==owner) then withdrawAll must succeed (reverted==false) and contract balance becomes zero.
        // - If provided caller != owner and this contract is not owner, then withdraw attempts must revert (reverted==true) and balance unchanged.
        // We encode these as one boolean formula.
        bool depositEffect = (depositAmount > 0) ? (afterDepositsCount == beforeDepositsCount + 1) : (afterDepositsCount == beforeDepositsCount);

        bool ownerCaseHandled;
        if (caller == owner && address(this) == owner) {
            // we attempted withdrawAll as actual owner; it must succeed and drain all funds
            ownerCaseHandled = (reverted == false) && (afterBalance == 0);
        } else if (caller != owner && address(this) != owner) {
            // non-owner attempt: withdraw call must revert and balance unchanged
            ownerCaseHandled = (reverted == true) && (afterBalance == beforeBalance);
        } else {
            // mixed/unrepresentable cases (e.g., caller==owner but this contract is not owner)
            // In those cases we only require that if call reverted then balance did not increase, and if it didn't revert then balance is <= beforeBalance (withdraw cannot create funds).
            ownerCaseHandled = reverted ? (afterBalance == beforeBalance) : (afterBalance <= beforeBalance);
        }

        assert(depositEffect && ownerCaseHandled);
    }

    // allow receiving Ether when c.withdraw transfers to this contract
    receive() external payable {}
}

