    // single public entry performing the test
    function run(address caller, bool asOwner, uint withdrawAmount) public payable {
        require(true);

        // Ensure this contract has enough balance to fund tests if needed
        // We won't send Ether to c here except via deposit through low-level call; instead we rely on c's initial state (freshly deployed)

        // Capture initial observable state
        uint beforeBalance = address(c).balance;
        uint beforeDepositsCount = c.depositsCount();

        bool reverted;

        // If asOwner is true, InvMutTest is the owner because constructor deployed c with msg.sender = this contract.
        // To simulate non-owner, we perform the withdraw call via a low-level call from an external address by calling a helper contract address (which does not exist) using call to c.withdraw.
        // However we must obey constraints: every state-changing call on c must be top-level. We'll attempt two top-level calls depending on asOwner.

        if (asOwner) {
            // invoke withdraw as owner (this contract)
            // ensure this contract has at least withdrawAmount to send back: but withdraw will transfer from c to this contract, so no precondition
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // simulate a non-owner by performing a call to c.withdraw via address.call from this contract but with data encoded for withdraw — msg.sender will still be this contract, so to truly be non-owner we instead call c.withdraw through a low-level call on address(c) with delegatecall? delegatecall would preserve msg.sender; can't change msg.sender in solidity here.
            // The checker runs run once from external EOA; we cannot create another caller. Instead we assert the general rule in terms of owner vs non-owner observable: if caller is not owner (asOwner == false) then withdraw must revert when called from this contract because this contract is the owner; to make a meaningful rule different from trivial, we instead check that withdraw reverts when withdrawAmount > address(c).balance for owner, and succeeds otherwise.

            // For non-owner paths we still perform the call to observe behaviour: call withdraw and record revert flag.
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalance = address(c).balance;
        uint afterDepositsCount = c.depositsCount();

        // General rule asserted:
        // If the call did not revert, then either (1) it was a withdraw by the owner and c's balance decreased by exactly withdrawAmount (bounded by prior balance),
        // and depositsCount did not change; or (2) if it reverted then c's balance and depositsCount are unchanged.
        // We express: reverted => balances and deposits unchanged. !reverted => deposits unchanged and beforeBalance >= afterBalance and (beforeBalance - afterBalance) == (withdrawAmount <= beforeBalance ? withdrawAmount : beforeBalance)

        if (reverted) {
            assert(afterBalance == beforeBalance && afterDepositsCount == beforeDepositsCount);
        } else {
            // depositsCount should not change for withdraw
            bool depositsUnchanged = (afterDepositsCount == beforeDepositsCount);
            // balance decreased or stayed same
            bool balanceNonIncrease = (afterBalance <= beforeBalance);
            uint expectedDecrease = withdrawAmount <= beforeBalance ? withdrawAmount : beforeBalance;
            bool exactDecrease = (beforeBalance - afterBalance) == expectedDecrease;
            assert(depositsUnchanged && balanceNonIncrease && exactDecrease);
        }
    }

    receive() external payable { }
}

