contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run simulates a non-owner sending Ether to c via a plain transfer (receive()).
    // amount is the Ether sent to c; callerIsOwner indicates whether this contract should have been the owner.
    // We require this contract not be the owner, so the receive() must revert (since only the deployer was owner),
    // and depositsCount and balance of c must remain unchanged after the attempted send.
    function run(uint amount, bool callerIsOwner) public payable {
        require(true);
        // Ensure this test contract has enough balance to send amount
        if (amount > 0) require(address(this).balance >= amount);

        // Read before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Ensure our contract is not the owner: if it is, the intended property doesn't apply, so force a revert by requiring false when callerIsOwner true.
        // We cannot read c.owner() in a require (view calls ok), so use it to check and require mismatch when callerIsOwner asserted.
        address owner = c.owner();
        if (callerIsOwner) {
            // If the caller claims it is owner, make sure it's true; otherwise don't proceed with the test
            require(owner == address(this));
        } else {
            // If callerIsOwner==false, require that this contract is NOT the owner so the test is meaningful
            require(owner != address(this));
        }

        // Attempt to send Ether to c to trigger receive(). Catch whether it reverted.
        bool reverted;
        // Use low-level call from this contract to c with provided amount
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: when this contract is NOT the owner (callerIsOwner==false), any attempt to send Ether to c must revert
        // and both depositsCount and balance must remain unchanged. If callerIsOwner==true, we don't assert anything here.
        assert(callerIsOwner || (reverted && afterDeposits == beforeDeposits && afterBal == beforeBal));
    }

    // Allow this test contract to receive Ether so it can fund the attempted send
    receive() external payable {}
}

